// The Queens' walls, part 2 (DICTO 2026-11-16): the cats of the two Queens, after the papers Silent Running (#109) and Walls of
// Silence (#110) and their studies (2026-11-16-600cell-walls, queens-construct, redqueen-cats, non-heart-vacuus). Pure maths, no three.js.
// DICTO · dictospheres.com
// Everything is computed from the Queens world's exact models (white-queen-geometry.js, red-queen-geometry.js) in the same 4D frame:
//   - The 5-cell's symmetry group S5 inside the White Queen: generated by four of her mirror reflections in an A4 chain; it splits her 120
//     corners into its five orbits A, −A, C3 (20 each), B, −B (30 each) (Koca, Koç, Al-Barwani and Al-Farsi's split). A is the hull of
//     the 20 permutations of (φ², φ², φ², φ, 0), B of the 30 permutations of (φ², φ², 1, 1, 0) (Silent Running).
//   - The Vacuus of a solid about the centre: its plates (the hyperplane through the centre spanned by each 2-face) and fins (the cone
//     from the centre over each 2-face); the kinds heart / inherited heart / non-heart (DICTO's names; Walls of Silence §2).
//   - The walls of the White Queen: her 60 mirrors (normal along a corner) and her 300 cross walls (normal along a cell centre, that is
//     along a corner of the Red Queen).
//   - The Red Queen's 10 inscribed White Queens (Coxeter's compound of ten 600-cells), in two states of 5, and the copies of A, B, C3
//     inside them; the polar duals A*, −A*, C3*, B*, −B* about the common centre with r² = |Red Queen corner|², for which the White
//     Queen's polar is the Red Queen.
// Heavy pieces are computed on first use and kept (memo), so loading the app costs nothing.
import { MIRRORS, QW_VERTICES, QW_RADIUS, QW_SHEETS } from './queens-walls-geometry.js';

export const PHI = (1 + Math.sqrt(5)) / 2;
const EPS = 1e-7;
const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);
const sub = (a, b) => a.map((x, i) => x - b[i]);
const norm = (a) => Math.hypot(...a);
const unit = (a) => { const l = norm(a); return a.map((x) => x / l); };
const keyOf = (x) => x.map((c) => Math.round(c * 1e5) + 0).join(',');
/** One sign for a direction up to sign: the first coordinate that is not zero is positive. */
export const canon = (n) => { const k = n.findIndex((x) => Math.abs(x) > 1e-6); return n[k] < 0 ? n.map((x) => -x) : n.slice(); };
const memo = (f) => { let v; return () => (v ??= f()); };

const det3 = (a, b, c) => a[0] * (b[1] * c[2] - b[2] * c[1]) - a[1] * (b[0] * c[2] - b[2] * c[0]) + a[2] * (b[0] * c[1] - b[1] * c[0]);
/** The 4D cross product of three vectors: perpendicular to all three (zero when they are dependent). */
export function cross4(a, b, c) {
  const m = (k) => [a, b, c].map((v) => v.filter((_, i) => i !== k));
  return [0, 1, 2, 3].map((k) => (k % 2 ? -1 : 1) * det3(...m(k)));
}

/**
 * The convex hull of 4D points around the origin (the origin inside), by brute force over 4-point subsets (fine up to a few dozen
 * points): { facets: [{ n (unit), h, verts }], faces: [corner loops (2-faces)], edges: [[i, j]] }.
 */
export function hull4(P) {
  const N = P.length, facets = [], seen = new Set();
  for (let a = 0; a < N; a++) for (let b = a + 1; b < N; b++) for (let c = b + 1; c < N; c++) for (let d = c + 1; d < N; d++) {
    const x = cross4(sub(P[b], P[a]), sub(P[c], P[a]), sub(P[d], P[a])), l = norm(x);
    if (l < 1e-9) continue;
    let n = x.map((v) => v / l), h = dot(n, P[a]), pos = 0, neg = 0;
    for (let p = 0; p < N && !(pos && neg); p++) { const s = dot(n, P[p]) - h; if (s > EPS) pos++; else if (s < -EPS) neg++; }
    if (pos && neg) continue;
    if (pos) { n = n.map((v) => -v); h = -h; }
    const verts = []; for (let p = 0; p < N; p++) if (Math.abs(dot(n, P[p]) - h) < EPS) verts.push(p);
    const k = verts.join(',');
    if (seen.has(k)) continue;
    seen.add(k); facets.push({ n, h, verts });
  }
  const faces = [];
  for (let i = 0; i < facets.length; i++) for (let j = i + 1; j < facets.length; j++) {
    const B = new Set(facets[j].verts), S = facets[i].verts.filter((v) => B.has(v));
    if (S.length >= 3) faces.push(loop(P, S));
  }
  const ek = new Set(), edges = [];
  for (const f of faces) f.forEach((a, i) => { const b = f[(i + 1) % f.length], k = a < b ? `${a},${b}` : `${b},${a}`; if (!ek.has(k)) { ek.add(k); edges.push(a < b ? [a, b] : [b, a]); } });
  return { facets, faces, edges };
}
/** The corners of a flat polygon in 4D in their order round it. */
function loop(P, S) {
  const c = [0, 1, 2, 3].map((k) => S.reduce((s, i) => s + P[i][k], 0) / S.length);
  const e1 = unit(sub(P[S[0]], c));
  let e2 = null;
  for (const i of S.slice(1)) { const v = sub(P[i], c), w = v.map((x, k) => x - dot(v, e1) * e1[k]); if (norm(w) > 1e-6) { e2 = unit(w); break; } }
  return S.map((i) => { const v = sub(P[i], c); return [i, Math.atan2(dot(v, e2), dot(v, e1))]; }).sort((p, q) => p[1] - q[1]).map((p) => p[0]);
}

/** The plates of a hull's 2-faces: [{ normal (unit, canonical sign), faces: [face indices] }], faces on one plate grouped. */
export function platesOf(P, faces) {
  const plates = [];
  faces.forEach((f, fi) => {
    const n = canon(unit(cross4(P[f[0]], P[f[1]], P[f[2]])));
    const pl = plates.find((p) => Math.abs(dot(p.normal, n)) > 1 - 1e-9);
    if (pl) pl.faces.push(fi); else plates.push({ normal: n, faces: [fi] });
  });
  return plates;
}

/** The kind of a solid's Vacuus about the centre (Walls of Silence, Lemma 1 and §2): heart when it is centrally symmetric; otherwise
 *  non-heart when every plate carries one face, inherited heart when some plate carries two or more. */
export function kindOf(P, plates) {
  const K = new Set(P.map(keyOf));
  if (P.every((x) => K.has(keyOf(x.map((c) => -c))))) return 'heart';
  return plates.every((p) => p.faces.length === 1) ? 'nonheart' : 'inherited';
}

/** A solid from its corners: hull, plates and kind, in one object. */
export function solid(P) {
  const h = hull4(P), plates = platesOf(P, h.faces);
  return { corners: P, ...h, plates, kind: kindOf(P, plates) };
}

/**
 * The S5s inside a 600-cell (its corners V, any radius): each generated by the reflections in four corners r1..r4 in an A4 chain
 * (consecutive ones at 120°, the others at 90°); one per set of 20 A4 roots, ±(r_i + … + r_j). [{ simple: [4 corner indices], roots }].
 */
export function s5sOf(V) {
  const r2 = dot(V[0], V[0]), at = new Map(V.map((x, i) => [keyOf(x), i]));
  const is = (i, j, c) => Math.abs(dot(V[i], V[j]) - c * r2) < 1e-6 * r2;
  const n120 = V.map((_, i) => V.map((_, j) => j).filter((j) => is(i, j, -0.5)));
  const out = [], seen = new Set();
  for (let a = 0; a < V.length; a++) for (const b of n120[a]) for (const c of n120[b]) {
    if (!is(c, a, 0)) continue;
    for (const d of n120[c]) {
      if (!is(d, a, 0) || !is(d, b, 0)) continue;
      const s = [a, b, c, d], roots = [];
      for (let i = 0; i < 4; i++) for (let j = i; j < 4; j++) {
        const v = [0, 1, 2, 3].map((k) => s.slice(i, j + 1).reduce((t, m) => t + V[m][k], 0));
        for (const w of [v, v.map((x) => -x)]) { const r = at.get(keyOf(w)); if (r === undefined) throw new Error('not a root system'); roots.push(r); }
      }
      const k = [...roots].sort((p, q) => p - q).join(',');
      if (seen.has(k)) continue;
      seen.add(k); out.push({ simple: s, roots });
    }
  }
  return out;
}

export const ORBITS = ['A', '-A', 'C3', 'B', '-B'];
/**
 * The five orbits of one S5 on a 600-cell's corners: { A, -A, C3, B, -B } as corner index lists. Each corner gets coordinates in the
 * sum-zero space of R⁵ (y_k − y_{k+1} = 2 x·r_k / r²) and is read by its pattern: A three equal at the top (φ², φ², φ², φ, 0), −A three
 * equal at the bottom, C3 three equal in the middle (a root), B two pairs and the single one at the bottom (φ², φ², 1, 1, 0), −B the single
 * one at the top. Which of the two 20-orbits is A (and which 30 is B) depends on the chain's sign; the pair is fixed by the S5.
 */
export function orbitsOf(V, s5) {
  const r2 = dot(V[0], V[0]), out = Object.fromEntries(ORBITS.map((k) => [k, []]));
  const eq = (p, q) => Math.abs(p - q) < 1e-6;
  V.forEach((x, i) => {
    const d = s5.simple.map((r) => (2 * dot(x, V[r])) / r2), y = [0];
    for (const t of d) y.push(y[y.length - 1] - t);
    const v = y.sort((p, q) => p - q);
    let o;
    if (eq(v[1], v[2]) && eq(v[2], v[3])) o = 'C3';
    else if (eq(v[2], v[3]) && eq(v[3], v[4])) o = 'A';
    else if (eq(v[0], v[1]) && eq(v[1], v[2])) o = '-A';
    else if (eq(v[3], v[4]) && eq(v[1], v[2])) o = 'B';
    else if (eq(v[0], v[1]) && eq(v[2], v[3])) o = '-B';
    else throw new Error('corner in no orbit');
    out[o].push(i);
  });
  return out;
}

// ---- the White Queen and her walls ----
const WQ = QW_VERTICES.white, RQ = { V: QW_VERTICES.red, R: QW_RADIUS.red };

/** The White Queen's walls: 60 mirrors (normal along a corner; the Queens' walls' MIRRORS, in the order of its sheets) and 300 cross
 *  walls (normal along a cell centre = a Red Queen corner). */
export const whiteWalls = memo(() => {
  const cross = [];
  for (const x of RQ.V) { const n = canon(unit(x)); if (!cross.some((m) => Math.abs(dot(m, n)) > 1 - 1e-9)) cross.push(n); }
  return { mirrors: MIRRORS, cross };
});
/** Which wall a plate normal is: { kind: 'mirror' | 'cross' | null, index }. */
export function wallOf(n, walls = whiteWalls()) {
  for (const kind of ['mirrors', 'cross']) { const i = walls[kind].findIndex((m) => Math.abs(dot(m, n)) > 1 - 1e-9); if (i >= 0) return { kind: kind === 'mirrors' ? 'mirror' : 'cross', index: i }; }
  return { kind: null, index: -1 };
}

/** The S5 shown in the world: the first found in the White Queen (one of her 60, all alike under her symmetry). */
export const whiteS5 = memo(() => s5sOf(WQ)[0]);
/** The five orbits of that S5 as solids on the White Queen's corners (4D points), each with its plates and their walls. */
export const whiteCats = memo(() => {
  const o = orbitsOf(WQ, whiteS5());
  return Object.fromEntries(ORBITS.map((k) => {
    const s = solid(o[k].map((i) => WQ[i]));
    for (const p of s.plates) p.wall = wallOf(p.normal);
    return [k, { ...s, index: o[k] }];
  }));
});

// ---- the Red Queen's inscribed White Queens ----
/**
 * The 600-cells inscribed in the Red Queen (on her corners): from each corner, its 24 neighbours at 36° fall into two icosahedra of 12,
 * and each icosahedron with the corner closes, under reflection in its own members, into one 600-cell. Returns { cells: [10 × 120 corner
 * indices], states: [[5 cell indices], [5 cell indices]] } (a state: five 600-cells with no corner in common).
 */
export const inscribed = memo(() => {
  const Q = RQ.V, r2 = dot(Q[0], Q[0]), at = new Map(Q.map((x, i) => [keyOf(x), i])), c36 = (PHI / 2) * r2;
  const near = (i, j) => Math.abs(dot(Q[i], Q[j]) - c36) < 1e-6 * r2;
  const cells = [], keys = new Set(), count = new Array(Q.length).fill(0);
  for (let v = 0; v < Q.length && cells.length < 10; v++) {
    if (count[v] >= 2) continue;
    const nb = Q.map((_, j) => j).filter((j) => near(v, j));
    const left = new Set(nb);
    while (left.size) {
      const comp = [], stack = [left.values().next().value];
      left.delete(stack[0]);
      while (stack.length) { const x = stack.pop(); comp.push(x); for (const y of [...left]) if (near(x, y)) { left.delete(y); stack.push(y); } }
      const S = [v, ...comp], inS = new Set(S);
      for (let q = 0; q < S.length; q++) {
        const x = S[q];
        for (let p = 0; p <= q; p++) {
          for (const [a, b] of [[x, S[p]], [S[p], x]]) {
            const A = Q[a], B = Q[b], f = (2 * dot(A, B)) / r2, img = at.get(keyOf(A.map((c, k) => c - f * B[k])));
            if (img === undefined) throw new Error('reflection off the Red Queen');
            if (!inS.has(img)) { inS.add(img); S.push(img); }
          }
        }
      }
      const k = [...S].sort((p, q) => p - q).join(',');
      if (!keys.has(k)) { keys.add(k); cells.push([...S].sort((p, q) => p - q)); S.forEach((i) => count[i]++); }
    }
  }
  const meet = (i, j) => { const B = new Set(cells[j]); return cells[i].filter((x) => B.has(x)).length; };
  const one = [0, ...cells.map((_, j) => j).filter((j) => j > 0 && meet(0, j) === 0)];
  const two = cells.map((_, j) => j).filter((j) => !one.includes(j));
  return { cells, states: [one, two], meet };
});
/** The edges of an inscribed 600-cell (pairs of its corners at 36°): 720. */
export function inscribedEdges(ci) {
  const Q = RQ.V, cell = inscribed().cells[ci], r2 = dot(Q[0], Q[0]), c36 = (PHI / 2) * r2, out = [];
  for (let a = 0; a < cell.length; a++) for (let b = a + 1; b < cell.length; b++) if (Math.abs(dot(Q[cell[a]], Q[cell[b]]) - c36) < 1e-6 * r2) out.push([cell[a], cell[b]]);
  return out;
}
const copiesCache = new Map();
/** The copies of A, −A, C3, B, −B inside one inscribed 600-cell: its 60 S5s, each with its five orbits (Red Queen corner indices). */
export function copiesIn(ci) {
  if (copiesCache.has(ci)) return copiesCache.get(ci);
  const cell = inscribed().cells[ci], V = cell.map((i) => RQ.V[i]);
  const list = s5sOf(V).map((s) => { const o = orbitsOf(V, s); return Object.fromEntries(ORBITS.map((k) => [k, o[k].map((i) => cell[i])])); });
  copiesCache.set(ci, list);
  return list;
}
/** The type of an orbit: A-type (A, −A), B-type (B, −B) or C3. */
export const TYPE = { A: 'A', '-A': 'A', B: 'B', '-B': 'B', C3: 'C3' };
/** The A-type or B-type copies of one state, in order (600-cell by 600-cell, S5 by S5, then + before −): [{ cell, orbit, corners }]. */
export function stateCopies(state, type) {
  const out = [];
  for (const ci of inscribed().states[state]) for (const o of copiesIn(ci)) for (const k of ORBITS) if (TYPE[k] === type) out.push({ cell: ci, orbit: k, corners: o[k] });
  return out;
}

// ---- the dual cats ----
/** Polarity about the centre with r²: the polar of a solid (corners → its facets' polar points). */
export const polarCorners = (s, r2) => s.facets.map((f) => f.n.map((x) => (r2 * x) / f.h));
/** The Red Queen's own cats: the polars of the White Queen's five orbits (the S5 of whiteS5), r² = |Red Queen corner|²; each a solid with
 *  its plates matched to the 60 mirrors (index into whiteWalls().mirrors, the same order as the Queens' walls' sheets). */
export const dualCats = memo(() => {
  const r2 = RQ.R * RQ.R, cats = whiteCats(), W = whiteWalls();
  return Object.fromEntries(ORBITS.map((k) => {
    const s = solid(polarCorners(cats[k], r2));
    for (const p of s.plates) { p.wall = wallOf(p.normal, W); p.covers = coverOn(s, p); }
    return [k, s];
  }));
});
/** Is the 4D point x in the cone from the centre over the face (corner loop) of a solid, on the face's plate (normal n)? */
function inCone(C, face, n, x) {
  const c = [0, 1, 2, 3].map((k) => face.reduce((t, i) => t + C[i][k], 0));
  if (Math.abs(dot(x, n)) > 1e-7 * norm(x)) return false;
  return face.every((a, i) => { const m = cross4(C[a], C[face[(i + 1) % face.length]], n); return dot(m, x) * Math.sign(dot(m, c)) >= -1e-7 * norm(x) * norm(m); });
}
/** The Red Queen's pentagons on a dual's plate (a mirror) that its fins cover: { whole: [pentagon indices in that sheet], partly: [...] }
 *  (whole: each corner and the centre lie in a fin on that plate; partly: the centre does but some corner does not). */
function coverOn(s, p) {
  const V = QW_VERTICES.red, sheet = QW_SHEETS.red[p.wall.index], whole = [], partly = [];
  if (p.wall.kind !== 'mirror') return { whole, partly };
  sheet.faces.forEach((pent, j) => {
    const pts = [...pent.map((i) => V[i]), [0, 1, 2, 3].map((k) => pent.reduce((t, i) => t + V[i][k], 0) / pent.length)];
    const inside = pts.map((x) => p.faces.some((fi) => inCone(s.corners, s.faces[fi], p.normal, x)));
    if (inside.every(Boolean)) whole.push(j); else if (inside[pts.length - 1]) partly.push(j);
  });
  return { whole, partly };
}
/** The radius of the largest dual (A*: its five big corners at φ² times the Red Queen's radius). */
export const dualRadius = memo(() => Math.max(...Object.values(dualCats()).flatMap((s) => s.corners.map(norm))));
